create trigger qa_upload after insert on public.listen_bar_tracks for each row execute function public.listen_bar_count_creator_upload();
do $$
declare u uuid := '00000000-0000-4000-8000-000000000001'; author uuid := '00000000-0000-4000-8000-000000000002';
  spender uuid := '00000000-0000-4000-8000-000000000003'; owner uuid := '00000000-0000-4000-8000-000000000004';
  work uuid; work2 uuid; comment uuid; old_comment uuid; result jsonb; n bigint; balance bigint; good text := '副歌旋律很有記憶點鼓組節奏清楚人聲中頻可以再柔和一些';
begin
  if not public.creator_credit_review_valid(good) or public.creator_credit_review_valid('短留言')
    or public.creator_credit_review_valid(repeat('哈哈',20)) or public.creator_credit_review_valid(repeat('太好聽了',10)) then raise exception 'Basic review validation failed'; end if;
  update public.mv_work_ratings set score=9.2 where track_id='00000000-0000-4000-8000-000000000050' and user_id=u;
  if exists(select 1 from public.creator_credit_participation_entries where user_id=u) then raise exception 'Old review was backfilled'; end if;
  result := public.creator_credit_visit(u);
  if (result->>'awarded')::integer<>15 or (result->>'balance')::integer<>18 then raise exception 'Daily or historical balance failed'; end if;
  result := public.creator_credit_visit(u);
  if (result->>'awarded')::integer<>0 then raise exception 'Daily retry minted twice'; end if;
  perform set_config('request.jwt.claim.sub',author::text,true);
  insert into public.listen_bar_tracks(created_by) values(author) returning id into work;
  insert into public.listen_bar_tracks(created_by) values(author) returning id into work2;
  insert into public.listen_bar_track_reactions(user_id,track_id,reaction) values(u,work,'heart');
  update public.listen_bar_track_reactions set reaction='heart' where user_id=u and track_id=work;
  select sum(delta) into balance from public.creator_credit_history where user_id=u;
  if balance<>21 then raise exception 'Heart retry minted twice'; end if;
  delete from public.listen_bar_track_reactions where user_id=u and track_id=work;
  insert into public.listen_bar_track_reactions(user_id,track_id,reaction) values(u,work,'heart');
  select sum(delta) into balance from public.creator_credit_history where user_id=u;
  if balance<>21 then raise exception 'Heart same award restoration failed'; end if;
  insert into public.listen_bar_track_reactions(user_id,track_id,reaction) values(author,work,'heart');
  if exists(select 1 from public.creator_credit_history where user_id=author) then raise exception 'Self Heart rewarded'; end if;
  insert into public.listen_bar_track_comments(user_id,track_id,body) values(u,work,good) returning id into comment;
  insert into public.mv_work_ratings(user_id,track_id,score,comment_id) values(u,work,8.7,comment);
  select sum(delta) into balance from public.creator_credit_history where user_id=u;
  if balance<>31 then raise exception 'Review not awarded'; end if;
  -- Adding a short discussion does not revoke an earlier valid awarded review.
  insert into public.listen_bar_track_comments(user_id,track_id,body) values(u,work,'新的短留言') returning id into old_comment;
  update public.mv_work_ratings set comment_id=old_comment where user_id=u and track_id=work;
  if (select sum(delta) from public.creator_credit_history where user_id=u)<>31 then raise exception 'Short discussion revoked another review'; end if;
  delete from public.listen_bar_track_comments where id=old_comment;
  update public.mv_work_ratings set score=9.1 where user_id=u and track_id=work;
  update public.listen_bar_track_comments set body='短留言' where id=comment;
  select sum(delta) into balance from public.creator_credit_history where user_id=u;
  if balance<>21 then raise exception 'Invalid edit not reclaimed'; end if;
  update public.listen_bar_track_comments set body=good where id=comment;
  perform public.edit_work_review(u,comment,good,false);
  select sum(delta) into balance from public.creator_credit_history where user_id=u;
  if balance<>21 then raise exception 'Author withdrawal not reclaimed'; end if;
  perform public.edit_work_review(u,comment,good,true);
  insert into public.listen_bar_track_comments(user_id,track_id,body) values(u,work2,good) returning id into old_comment;
  insert into public.mv_work_ratings(user_id,track_id,score,comment_id) values(u,work2,7.2,old_comment);
  select sum(delta) into balance from public.creator_credit_history where user_id=u;
  if balance<>31 then raise exception 'Copied review rewarded'; end if;
  update public.listen_bar_track_comments set moderation_status='hidden',moderation_note='moderator' where id=comment;
  begin perform public.edit_work_review(u,comment,good,true); raise exception 'Author restored moderated content'; exception when insufficient_privilege then null; end;
  -- Paid flow and debt: four synthetic visits fund exactly one extra submission.
  for i in 1..4 loop insert into public.creator_credit_participation_entries(user_id,delta,reason,source_id,event_key) values(spender,15,'daily_visit',gen_random_uuid(),'qa:visit:'||i); end loop;
  perform set_config('request.jwt.claim.sub',spender::text,true);
  for i in 1..3 loop insert into public.listen_bar_tracks(created_by) values(spender); end loop;
  begin insert into public.listen_bar_tracks(created_by) values(spender); raise exception 'Missing consent allowed'; exception when raise_exception then if sqlerrm not like 'CREDIT_CONFIRM_REQUIRED%' then raise; end if; end;
  insert into public.listen_bar_tracks(created_by,credit_submission_confirmed) values(spender,true);
  select sum(delta) into balance from public.creator_credit_history where user_id=spender;
  if balance<>0 then raise exception 'Extra work debit failed'; end if;
  begin insert into public.listen_bar_tracks(created_by,credit_submission_confirmed) values(spender,true); raise exception 'Overspend allowed'; exception when raise_exception then if sqlerrm not like 'CREDIT_INSUFFICIENT%' then raise; end if; end;
  insert into public.listen_bar_track_reactions(user_id,track_id,reaction) values(spender,work,'heart');
  for i in 1..19 loop insert into public.creator_credit_entries(user_id,delta,reason,source_id) values(spender,3,'blind_compare',gen_random_uuid()); end loop;
  insert into public.listen_bar_tracks(created_by,credit_submission_confirmed) values(spender,true);
  delete from public.listen_bar_track_reactions where user_id=spender and track_id=work;
  result := public.listen_bar_my_upload_quota();
  if (result->>'balance')::integer<>0 or (result->>'debt')::integer<>3 or (result->>'canSubmit')::boolean then raise exception 'Debt policy failed'; end if;
  begin insert into public.listen_bar_tracks(created_by,credit_submission_confirmed) values(spender,true); raise exception 'Debt spending allowed'; exception when raise_exception then if sqlerrm not like 'CREDIT_DEBT%' then raise; end if; end;
  result := public.creator_credit_visit(spender);
  if (result->>'balance')::integer<>12 or (result->>'debt')::integer<>0 then raise exception 'Income debt recovery failed'; end if;
  update public.listen_bar_creator_upload_windows set started_at=clock_timestamp()-interval '169 hours' where creator_id=spender;
  insert into public.listen_bar_tracks(created_by) values(spender);
  if (select upload_count from public.listen_bar_creator_upload_windows where creator_id=spender)<>1 then raise exception '168h reset failed'; end if;
  select count(*) into n from public.listen_bar_tracks where created_by=spender;
  begin insert into public.listen_bar_tracks(created_by) values(spender); raise exception 'simulate storage confirmation failure'; exception when raise_exception then null; end;
  if (select count(*) from public.listen_bar_tracks where created_by=spender)<>n or (select upload_count from public.listen_bar_creator_upload_windows where creator_id=spender)<>1 then raise exception 'Failed work changed quota'; end if;
  perform set_config('request.jwt.claim.sub',owner::text,true);
  for i in 1..6 loop insert into public.listen_bar_tracks(created_by) values(owner); end loop;
  if exists(select 1 from public.creator_credit_history where user_id=owner) or exists(select 1 from public.listen_bar_creator_upload_windows where creator_id=owner) then raise exception 'Owner charged or limited'; end if;
  if not (public.listen_bar_my_upload_quota()->>'unlimited')::boolean then raise exception 'Owner display failed'; end if;
  if has_function_privilege('authenticated','public.creator_credit_visit(uuid)','execute') or has_table_privilege('authenticated','public.creator_credit_awards','select') then raise exception 'Private boundaries failed'; end if;
  if (select delta from public.creator_credit_history where source_id='00000000-0000-4000-8000-000000000099')<>3 then raise exception 'Historical blind receipt changed'; end if;
end;
$$;
